mapper.select:
select t.business_code, t.contract_number, t.name, t.model, t.related_party, t.in_storage_type, t1.accrual_await_qualified, t1.accrual_await_un_qualified, t.act_in_qualified, t.act_in_un_qualified, t.position_operation_codes::BIGINT[], t.operation_version, t.pieces_chn, t.operator_name, t.operation_time, t.related_party, t.detail_code, t.operation_version, t2.picture::BIGINT[], t.product_or_part, t.batch_num, t1.stored_num from ${inOrOutOperationDetailRecordTableName} t inner join ${inboundOrderDetailTableName} t1 on t.detail_code = t1.primary_key left join ${stockTableName} t2 on t1.stock = t2.primary_key where t.enterprise_code = #{enterpriseCode}
AND t.contract_number = #{request.oddNumbers}
and t.name = #{request.name}
and t.model = #{request.model}
and t.related_party LIKE '%' || #{request.relatedParty} || '%'
AND t.in_storage_type IN
#{item}
and t.operator = #{request.operator}
AND t.operation_time >= #{request.startTime}
AND t.operation_time <= #{request.endTime}
order by t1.create_time desc

select t1.business_code, t1.contract_number, t3.product_part_sign as name, t3.primary_key as product_or_part, t3.model, t3.Unity_No part_Unity_No, t1.related_party, t1.in_storage_type, t.stored_num, p.operation_num, COALESCE(t5.pieces_sign,'-') pieces_chn, t4.position_sign as position_name, t4.type as position_type, p.operator, p.operation_time, t.accrual_await_qualified, t.accrual_await_un_qualified, t.primary_key as detail_code, t2.picture::BIGINT[], t2.stock_init_state, t2.bar_code_number, p.check_batch_number from ${positionOperationTableName} p inner join ${inboundOrderDetailTableName} t on p.detail_code = t.primary_key inner join ${inboundOrderTableName} t1 on t.inbound_order = t1.primary_key left join ${stockTableName} t2 on t.stock = t2.primary_key left join ${productPartTableName} t3 on t2.product_part_code = t3.primary_key left join ${positionTableName} t4 on p.position = t4.primary_key left join ${piecesTableName} t5 on t3.pcs = t5.primary_key where p.enterprise_code = #{enterpriseCode} and p.detail_code is not null and p.delete_flag = false and t.delete_flag = false and t1.delete_flag = false
and ${dynamicTableNameProxy.getXiHangPartQuery("t2.product_part_code","xihang",request.partUnityNo)}
AND t1.contract_number = #{request.contractNum}
and t3.product_part_sign LIKE '%' || #{request.name} || '%'
and t2.bar_code_number LIKE '%' || #{request.barCodeNumber} || '%'
and t3.model LIKE '%' || #{request.model} || '%'
AND (t3.model like '%'|| #{request.searchName} ||'%' or t3.product_part_sign like '%'|| #{request.searchName} ||'%')
and t1.related_party LIKE '%' || #{request.relatedParty} || '%'
AND t1.in_storage_type IN
#{item}
and p.operator IN
#{item}
AND p.operation_time::date >= #{request.startTime}::date
AND p.operation_time::date <= #{request.endTime}::date
and t4.position_sign LIKE '%' || #{request.positionName} || '%'
and p.check_batch_number LIKE '%' || #{request.batch} || '%'
AND p.primary_key IN
#{code}
${dataScopeParams.dataScope}
order by p.operation_time asc NULLS LAST
order by p.operation_time desc NULLS LAST
LIMIT #{request.pageSize} OFFSET #{request.offset}

select t.business_code, t.contract_number, t.name, t.model, t.outbound_type, t1.accrual_out_total, t.act_out_num, t.position_operation_codes::BIGINT[], t.operation_version, t.pieces_chn, t.operator_name, t.operation_time, t.detail_code, t.operation_version, t2.picture::BIGINT[], t.remark, t.batch_num, t.product_or_part, t1.out_total from ${inOrOutOperationDetailRecordTableName} t inner join ${outboundOrderDetailTableName} t1 on t.detail_code = t1.primary_key left join ${stockTableName} t2 on t1.stcok = t2.primary_key where t.enterprise_code = #{enterpriseCode}
AND t.contract_number = #{request.oddNumbers}
and t.name = #{request.name}
and t.model = #{request.model}
AND t.outbound_type IN
#{item}
and t.operator = #{request.operator}
AND t.operation_time >= #{request.startTime}
AND t.operation_time <= #{request.endTime}
order by t1.create_time desc

-- select product_or_part, business_code, sum(a.operation_num) num, count(1)
select sum(a.operation_num) num

from ${positionOperation} a,
${inOrOutOperationDetailRecordTableName} b
where a.operation_version = b.operation_version
and b.outbound_type is not null
and business_code = #{contractCodeString}
and product_or_part = #{id}
and batch_global_code = #{batchGlobalCode}




        and a.stock_type in ('FGFXBL')


        and a.stock_type in ('SCLL','SCBL')



group by product_or_part, business_code

select * from ( select t.contract_code as business_code, t.contract_number, t3.product_part_sign as name, t3.primary_key as product_or_part, t3.model, t3.Unity_No part_Unity_No, t.related_party, t.order_quantity as stored_num, p.operation_num, COALESCE(t5.pieces_sign, '-') pieces_chn, t4.position_sign as position_name, t4.type as position_type, p.operator, p.operation_time, p.detail_code as detail_code, t2.picture::BIGINT[], t2.stock_init_state, t2.bar_code_number, p.check_batch_number, p.primary_key as positionOperationCode from ${positionOperationTableName} p inner join ${dynamicTableNameProxy.collaborateInboundItem} t on p.detail_code = t.primary_key left join ${stockTableName} t2 on t.collaborate_material = t2.product_part_code left join ${productPartTableName} t3 on t.collaborate_material = t3.primary_key left join ${positionTableName} t4 on p.position = t4.primary_key left join ${piecesTableName} t5 on t3.pcs = t5.primary_key where p.enterprise_code = #{enterpriseCode} and p.detail_code is not null and p.delete_flag = false and t.delete_flag = false
and ${dynamicTableNameProxy.getXiHangPartQuery("t3.primary_key","xihang",request.partUnityNo)}
and t4.position_sign LIKE '%' || #{request.positionName} || '%'
union all select p.contract_code as business_code, p.contract_number, t3.product_part_sign as name, t3.primary_key as product_or_part, t3.model, t3.Unity_No part_Unity_No, p.related_party, p.apply_num as stored_num, p.operation_num, COALESCE(t5.pieces_sign, '-') pieces_chn, t4.position_sign as position_name, t4.type as position_type, p.operator, p.operation_time, p.detail_code as detail_code, t2.picture::BIGINT[], t2.stock_init_state, t2.bar_code_number, p.check_batch_number, p.primary_key as positionOperationCode from ${positionOperationTableName} p left join ${stockTableName} t2 on p.material = t2.product_part_code left join ${productPartTableName} t3 on p.material = t3.primary_key left join ${positionTableName} t4 on p.position = t4.primary_key left join ${piecesTableName} t5 on t3.pcs = t5.primary_key where p.enterprise_code = #{enterpriseCode} and p.detail_code is not null and p.delete_flag = false and p.contract_code is not null and p.operation_type = false
and ${dynamicTableNameProxy.getXiHangPartQuery("t3.primary_key","xihang",request.partUnityNo)}
and t4.position_sign LIKE '%' || #{request.positionName} || '%'
) a
AND a.contract_number = #{request.contractNum}
and a.name LIKE '%' || #{request.name} || '%'
and a.bar_code_number LIKE '%' || #{request.barCodeNumber} || '%'
and a.model LIKE '%' || #{request.model} || '%'
AND (a.model like '%'|| #{request.searchName} ||'%' or a.name like '%'|| #{request.searchName} ||'%')
and a.related_party LIKE '%' || #{request.relatedParty} || '%'
and a.operator IN
#{item}
AND a.operation_time::date >= #{request.startTime}::date
AND a.operation_time::date <= #{request.endTime}::date
and a.check_batch_number LIKE '%' || #{request.batch} || '%'
AND a.positionOperationCode IN
#{code}
${dataScopeParams.dataScope}
order by a.operation_time asc NULLS LAST
order by a.operation_time desc NULLS LAST
LIMIT #{request.pageSize} OFFSET #{request.offset}

select * from ( WITH apply_summary AS ( SELECT data_key, COALESCE(SUM(apply_num), 0) AS apply_num_sum, COALESCE(SUM(CASE WHEN type = 'SCBL' THEN apply_num ELSE 0 END), 0) AS scbl_apply_num_sum FROM ${dynamicTableNameProxy.outStockApply} WHERE delete_flag = false GROUP BY data_key )
select t.contract_code as business_code, t.contract_number, t3.product_part_sign as name, t3.primary_key as product_or_part, t3.model, t3.Unity_No part_Unity_No, p.related_party, case when t.collaborate_type = 0 then t.order_quantity else GREATEST((COALESCE(t.order_quantity,0) - COALESCE(t.schedule_quantity,0) + COALESCE(a.scbl_apply_num_sum,0)), 0) end as out_total, p.operation_num, COALESCE(t5.pieces_sign, '-') pieces_chn, t4.position_sign as position_name, t4.type as position_type, p.operator, p.operation_time, p.detail_code as detail_code, t2.picture::BIGINT[], t2.stock_init_state, t2.bar_code_number, p.check_batch_number, p.primary_key as positionOperationCode, p.remark from ${positionOperationTableName} p inner join ${dynamicTableNameProxy.collaborateScheduleItem} t on p.detail_code = t.primary_key left join apply_summary a on t.primary_key = a.data_key left join ${stockTableName} t2 on t.collaborate_material = t2.product_part_code left join ${productPartTableName} t3 on t.collaborate_material = t3.primary_key left join ${positionTableName} t4 on p.position = t4.primary_key left join ${piecesTableName} t5 on t3.pcs = t5.primary_key where p.enterprise_code = #{enterpriseCode} and p.detail_code is not null and p.delete_flag = false and t.delete_flag = false and p.operation_type = true
and ${dynamicTableNameProxy.getXiHangPartQuery("t3.primary_key","xihang",request.partUnityNo)}
and t4.position_sign LIKE '%' || #{request.positionName} || '%'
union all select p.contract_code as business_code, p.contract_number, t3.product_part_sign as name, t3.primary_key as product_or_part, t3.model, t3.Unity_No part_Unity_No, p.related_party, p.apply_num as out_total, p.operation_num, COALESCE(t5.pieces_sign, '-') pieces_chn, t4.position_sign as position_name, t4.type as position_type, p.operator, p.operation_time, p.detail_code as detail_code, t2.picture::BIGINT[], t2.stock_init_state, t2.bar_code_number, p.check_batch_number, p.primary_key as positionOperationCode, p.remark from ${positionOperationTableName} p left join ${stockTableName} t2 on p.material = t2.product_part_code left join ${productPartTableName} t3 on p.material = t3.primary_key left join ${positionTableName} t4 on p.position = t4.primary_key left join ${piecesTableName} t5 on t3.pcs = t5.primary_key where p.enterprise_code = #{enterpriseCode} and p.detail_code is not null and p.delete_flag = false and p.contract_code is not null and p.operation_type = true
and ${dynamicTableNameProxy.getXiHangPartQuery("t3.primary_key","xihang",request.partUnityNo)}
and t4.position_sign LIKE '%' || #{request.positionName} || '%'
) a
AND a.contract_number = #{request.contractNum}
and a.name LIKE '%' || #{request.name} || '%'
and a.bar_code_number LIKE '%' || #{request.barCodeNumber} || '%'
and a.model LIKE '%' || #{request.model} || '%'
AND (a.model like '%'|| #{request.searchName} ||'%' or a.name like '%'|| #{request.searchName} ||'%')
and a.related_party LIKE '%' || #{request.relatedParty} || '%'
and a.operator IN
#{item}
AND a.operation_time::date >= #{request.startTime}::date
AND a.operation_time::date <= #{request.endTime}::date
and a.check_batch_number LIKE '%' || #{request.batch} || '%'
AND a.positionOperationCode IN
#{code}
${dataScopeParams.dataScope}
order by a.operation_time asc NULLS LAST
order by a.operation_time desc NULLS LAST
LIMIT #{request.pageSize} OFFSET #{request.offset}
